CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE `AlbumEntity` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `basename` TEXT NOT NULL, `artistId` TEXT NOT NULL, `artistName` TEXT NOT NULL, `artists` TEXT NOT NULL, `time` INTEGER NOT NULL, `year` INTEGER NOT NULL, `songCount` INTEGER NOT NULL, `diskCount` INTEGER NOT NULL, `genre` TEXT NOT NULL, `artUrl` TEXT NOT NULL, `flag` INTEGER NOT NULL, `rating` INTEGER NOT NULL, `averageRating` REAL NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', `searchName` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `SongEntity` (`mediaId` TEXT NOT NULL, `title` TEXT NOT NULL, `albumId` TEXT NOT NULL, `albumName` TEXT NOT NULL, `artistId` TEXT NOT NULL, `artistName` TEXT NOT NULL, `albumArtist` TEXT NOT NULL, `songUrl` TEXT NOT NULL, `imageUrl` TEXT NOT NULL, `bitrate` INTEGER NOT NULL, `streamBitrate` INTEGER NOT NULL, `catalog` INTEGER NOT NULL, `channels` INTEGER NOT NULL, `composer` TEXT NOT NULL, `filename` TEXT NOT NULL, `genre` TEXT NOT NULL, `mime` TEXT, `playCount` INTEGER NOT NULL, `playlistTrackNumber` INTEGER NOT NULL, `rateHz` INTEGER NOT NULL, `size` INTEGER NOT NULL, `time` INTEGER, `trackNumber` INTEGER NOT NULL, `year` INTEGER NOT NULL, `name` TEXT NOT NULL, `mode` TEXT, `artists` TEXT NOT NULL, `flag` INTEGER NOT NULL, `streamFormat` TEXT, `format` TEXT, `streamMime` TEXT, `publisher` TEXT, `replayGainTrackGain` REAL, `replayGainTrackPeak` REAL, `disk` INTEGER NOT NULL, `diskSubtitle` TEXT NOT NULL, `mbId` TEXT NOT NULL, `comment` TEXT NOT NULL, `language` TEXT NOT NULL, `lyrics` TEXT NOT NULL, `albumMbId` TEXT NOT NULL, `artistMbId` TEXT NOT NULL, `albumArtistMbId` TEXT NOT NULL, `averageRating` REAL NOT NULL, `preciseRating` REAL NOT NULL, `rating` REAL NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', `searchTitle` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`mediaId`));
CREATE TABLE `ArtistEntity` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `albumCount` INTEGER NOT NULL, `songCount` INTEGER NOT NULL, `genre` TEXT NOT NULL, `artUrl` TEXT NOT NULL, `flag` INTEGER NOT NULL, `summary` TEXT, `time` INTEGER NOT NULL, `yearFormed` INTEGER NOT NULL, `placeFormed` TEXT, `multiUserId` TEXT NOT NULL DEFAULT '', `searchName` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `PlaylistEntity` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `owner` TEXT NOT NULL, `items` INTEGER, `type` TEXT, `artUrl` TEXT, `flag` INTEGER NOT NULL, `preciseRating` REAL NOT NULL, `rating` INTEGER NOT NULL, `averageRating` REAL NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `SessionEntity` (`primaryKey` TEXT NOT NULL, `add` TEXT NOT NULL, `albums` INTEGER NOT NULL, `api` TEXT NOT NULL, `artists` INTEGER NOT NULL, `auth` TEXT NOT NULL, `catalogs` INTEGER NOT NULL, `clean` TEXT NOT NULL, `genres` INTEGER NOT NULL, `labels` INTEGER NOT NULL, `licenses` INTEGER NOT NULL, `liveStreams` INTEGER NOT NULL, `playlists` INTEGER NOT NULL, `playlistsSearches` INTEGER NOT NULL, `podcastEpisodes` INTEGER NOT NULL, `podcasts` INTEGER NOT NULL, `searches` INTEGER NOT NULL, `sessionExpire` TEXT NOT NULL, `shares` INTEGER NOT NULL, `songs` INTEGER NOT NULL, `update` TEXT NOT NULL, `users` INTEGER NOT NULL, `videos` INTEGER NOT NULL, PRIMARY KEY(`primaryKey`));
CREATE TABLE `CredentialsEntity` (`primaryKey` TEXT NOT NULL, `username` TEXT NOT NULL, `password` TEXT NOT NULL, `authToken` TEXT NOT NULL, `serverUrl` TEXT NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`primaryKey`));
CREATE TABLE `UserEntity` (`id` TEXT NOT NULL, `username` TEXT NOT NULL, `email` TEXT NOT NULL, `access` INTEGER NOT NULL, `streamToken` TEXT, `fullNamePublic` INTEGER NOT NULL, `fullName` TEXT, `disabled` INTEGER NOT NULL, `createDate` INTEGER NOT NULL, `lastSeen` INTEGER NOT NULL, `website` TEXT NOT NULL, `state` TEXT NOT NULL, `city` TEXT NOT NULL, `art` TEXT NOT NULL DEFAULT '', `serverUrl` TEXT NOT NULL DEFAULT '', `multiUserId` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `LocalSettingsEntity` (`username` TEXT NOT NULL, `theme` TEXT NOT NULL, `enableRemoteLogging` INTEGER NOT NULL DEFAULT false, `hideDonationButton` INTEGER NOT NULL DEFAULT false, `smartDownloadEnabled` INTEGER NOT NULL DEFAULT false, `enableAutoUpdates` INTEGER NOT NULL DEFAULT false, `streamingQuality` INTEGER NOT NULL DEFAULT 320, `isNormalizeVolumeEnabled` INTEGER NOT NULL DEFAULT false, `isMonoAudioEnabled` INTEGER NOT NULL DEFAULT false, `isGlobalShuffleEnabled` INTEGER NOT NULL DEFAULT false, `playlistSongsSorting` TEXT NOT NULL DEFAULT 'ASC', `isOfflineModeEnabled` INTEGER NOT NULL DEFAULT false, `isDownloadsSdCard` INTEGER NOT NULL DEFAULT false, `sleepTimerMinutes` INTEGER NOT NULL DEFAULT 0, `saveSongAfterPlayback` INTEGER NOT NULL DEFAULT false, `saveFavouriteSongAfterPlayback` INTEGER NOT NULL DEFAULT false, PRIMARY KEY(`username`));
CREATE TABLE `DownloadedSongEntity` (`mediaId` TEXT NOT NULL, `title` TEXT NOT NULL, `albumId` TEXT NOT NULL, `albumName` TEXT NOT NULL, `artistId` TEXT NOT NULL, `artistName` TEXT NOT NULL, `songUri` TEXT NOT NULL, `bitrate` INTEGER NOT NULL, `channels` INTEGER NOT NULL, `genre` TEXT NOT NULL, `mime` TEXT, `name` TEXT NOT NULL, `mode` TEXT, `streamFormat` TEXT, `format` TEXT, `disk` INTEGER NOT NULL, `composer` TEXT NOT NULL, `rateHz` INTEGER NOT NULL, `size` INTEGER NOT NULL, `time` INTEGER NOT NULL, `trackNumber` INTEGER NOT NULL, `year` INTEGER NOT NULL, `imageUrl` TEXT NOT NULL, `albumArtist` TEXT NOT NULL, `averageRating` REAL NOT NULL, `preciseRating` REAL NOT NULL, `rating` REAL NOT NULL, `lyrics` TEXT NOT NULL, `comment` TEXT NOT NULL, `language` TEXT NOT NULL, `relativePath` TEXT NOT NULL, `owner` TEXT NOT NULL, `flag` INTEGER NOT NULL DEFAULT false, `multiUserId` TEXT NOT NULL DEFAULT '', `searchTitle` TEXT NOT NULL DEFAULT '', `searchAlbum` TEXT NOT NULL DEFAULT '', `searchArtist` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`mediaId`));
CREATE TABLE `GenreEntity` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `albums` INTEGER NOT NULL, `artists` INTEGER NOT NULL, `songs` INTEGER NOT NULL, `playlists` INTEGER NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `PlaylistSongEntity` (`id` TEXT NOT NULL, `songId` TEXT NOT NULL, `playlistId` TEXT NOT NULL, `position` INTEGER NOT NULL, `multiUserId` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `MultiUserSessionEntity` (`add` TEXT NOT NULL, `albums` INTEGER NOT NULL, `api` TEXT NOT NULL, `artists` INTEGER NOT NULL, `auth` TEXT NOT NULL, `catalogs` INTEGER NOT NULL, `clean` TEXT NOT NULL, `genres` INTEGER NOT NULL, `labels` INTEGER NOT NULL, `licenses` INTEGER NOT NULL, `liveStreams` INTEGER NOT NULL, `playlists` INTEGER NOT NULL, `playlistsSearches` INTEGER NOT NULL, `podcastEpisodes` INTEGER NOT NULL, `podcasts` INTEGER NOT NULL, `searches` INTEGER NOT NULL, `sessionExpire` TEXT NOT NULL, `shares` INTEGER NOT NULL, `songs` INTEGER NOT NULL, `update` TEXT NOT NULL, `users` INTEGER NOT NULL, `videos` INTEGER NOT NULL, `username` TEXT NOT NULL, `serverUrl` TEXT NOT NULL, `primaryKey` TEXT NOT NULL, PRIMARY KEY(`primaryKey`));
CREATE TABLE `MultiUserEntity` (`id` TEXT NOT NULL, `username` TEXT NOT NULL, `email` TEXT NOT NULL, `access` INTEGER NOT NULL, `streamToken` TEXT, `fullNamePublic` INTEGER NOT NULL, `fullName` TEXT, `disabled` INTEGER NOT NULL, `createDate` INTEGER NOT NULL, `lastSeen` INTEGER NOT NULL, `website` TEXT NOT NULL, `state` TEXT NOT NULL, `city` TEXT NOT NULL, `serverUrl` TEXT NOT NULL, `primaryKey` TEXT NOT NULL, PRIMARY KEY(`primaryKey`));
CREATE TABLE `MultiUserCredentialEntity` (`username` TEXT NOT NULL, `password` TEXT NOT NULL, `authToken` TEXT NOT NULL, `serverUrl` TEXT NOT NULL, `primaryKey` TEXT NOT NULL, PRIMARY KEY(`primaryKey`));
CREATE TABLE `HistoryEntity` (`mediaId` TEXT NOT NULL, `playCount` INTEGER NOT NULL, `lastPlayed` INTEGER NOT NULL, `multiUserId` TEXT NOT NULL, `id` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `RecommendedArtistEntity` (`recommendedArtistId` TEXT NOT NULL, `baseArtistId` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `multiUserId` TEXT NOT NULL, `id` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
